                    if idx < len(header):
                        key = header[idx]
                    else:
                        key = str(idx+1)
                    rec[key] = infer_type(val) if not opts.infer_none else val
                records.append(rec)
    except csv.Error as e:
        eprint(f"mlr: CSV error: {e}")
        pass
    return records

def write_csv_records(records, opts, ofmt):
    if not records:
        return
    delimiter = ","
    if ofmt == "tsv" or ofmt == "tsvlite":
        delimiter = "\t"
    elif ofmt == "csvlite":
        delimiter = ","
    fieldnames = []
    seen=set()
    for rec in records:
        for k in rec.keys():
            if k not in seen:
                seen.add(k)
                fieldnames.append(k)
    output = io.StringIO()
    writer = csv.writer(output, delimiter=delimiter, quotechar='"', quoting=csv.QUOTE_MINIMAL, lineterminator=opts.ors if opts.ors else "\n")
    if not opts.headerless_output:
        writer.writerow(fieldnames)
    for rec in records:
        row=[]
        for fn in fieldnames:
            v = rec.get(fn, "")
            if v is None:
                v=""
            elif isinstance(v, (dict, list)):
                v = json.dumps(v)
            else:
                v = str(v) if not isinstance(v, str) else v
            row.append(v)
        writer.writerow(row)
    sys.stdout.write(output.getvalue())

def write_json_records(records, opts, fmt):
    if fmt == "jsonl":
        for rec in records:
            sys.stdout.write(json.dumps(dict(rec)) + "\n")
    else:
        output = json.dumps([dict(r) for r in records], indent=2)
        sys.stdout.write(output + "\n")

def infer_records_from_lines(lines, opts, ifmt):
    records=[]
    for line in lines:
        if line == "" and not opts.irs:
            continue
        if ifmt == "dkvp":
            rec = parse_record_line_dkvp(line, opts.ifs, opts.ips, opts.ips_regex)
            if not opts.infer_none:
                for k in list(rec.keys()):
                    rec[k] = infer_type(rec[k])
            records.append(rec)
        elif ifmt == "nidx":
            if opts.ifs_regex:
                try:
                    parts = re.split(opts.ifs_regex, line)
                    filtered=[]
                    for p in parts:
                        if p is None:
                            continue
                        if p != "":
                            try:
                                if re.fullmatch(opts.ifs_regex, p):
                                    continue
                            except:
                                pass
                            filtered.append(p)
                    parts = filtered
                except Exception as e:
                    parts = line.split(opts.ifs) if opts.ifs else [line]
            else:
                if opts.ifs == " ":
                    parts = re.split(r'\s+', line.strip())
                    parts = [p for p in parts if p != ""]
                else:
                    parts = line.split(opts.ifs) if opts.ifs else [line]
            rec = OrderedDict()
            for idx, val in enumerate(parts, start=1):
                k = str(idx)
                rec[k] = infer_type(val) if not opts.infer_none else val
            records.append(rec)
        else:
            rec = parse_record_line_dkvp(line, opts.ifs, opts.ips)
            records.append(rec)
    return records

def read_nidx_records(fileobj, opts):
    records=[]
    for raw in fileobj:
        if opts.skip_comments and raw.lstrip().startswith(opts.comment_prefix):
            continue
        if opts.pass_comments and raw.lstrip().startswith(opts.comment_prefix):
            sys.stdout.write(raw)
            continue
        line = raw.rstrip("\r\n")
        if line == "" and not opts.irs:
            continue
        if opts.ifs_regex:
            try:
                parts = re.split(opts.ifs_regex, line)
                filtered=[]
                for p in parts:
                    if p is None:
                        continue
                    if p == "":
                        continue
                    try:
                        if re.fullmatch(opts.ifs_regex, p):
                            continue
                    except:
                        pass
                    filtered.append(p)
                parts = filtered
            except Exception:
                parts = line.split(opts.ifs) if opts.ifs else [line]
        else:
            if opts.ifs == " ":
                parts = re.split(r'\s+', line.strip())
                parts = [p for p in parts if p != ""]
            elif opts.ifs == "\t":
                parts = line.split("\t")
            else:
                parts = line.split(opts.ifs) if opts.ifs else [line]
        rec = OrderedDict()
        for idx, val in enumerate(parts, start=1):
            rec[str(idx)] = infer_type(val) if not opts.infer_none else val
        records.append(rec)
    return records

def read_dkvp_records(fileobj, opts):
    records=[]
    for raw in fileobj:
        if opts.skip_comments and raw.lstrip().startswith(opts.comment_prefix):
            continue
        if opts.pass_comments and raw.lstrip().startswith(opts.comment_prefix):
            sys.stdout.write(raw)
            continue
        line = raw.rstrip("\r\n")
        if line == "":
            continue
        rec = parse_record_line_dkvp(line, opts.ifs, opts.ips, opts.ips_regex)
        if not opts.infer_none:
            for k in list(rec.keys()):
                rec[k] = infer_type(rec[k])
        records.append(rec)
    return records

def read_pprint_records(fileobj, opts):
    lines = []
    for raw in fileobj:
        if opts.skip_comments and raw.lstrip().startswith(opts.comment_prefix):
            continue
        if opts.pass_comments and raw.lstrip().startswith(opts.comment_prefix):
            sys.stdout.write(raw)
            continue
        line = raw.rstrip("\r\n")
        if line.strip() == "":
            continue
        lines.append(line)
    if not lines:
        return []
    header = re.split(r'\s+', lines[0].strip())
    records=[]
    for line in lines[1:]:
        values = re.split(r'\s+', line.strip())
        rec = OrderedDict()
        for idx, h in enumerate(header):
            if idx < len(values):
                rec[h] = infer_type(values[idx]) if not opts.infer_none else values[idx]
            else:
                rec[h] = ""
        for idx in range(len(header), len(values)):
            rec[str(idx+1)] = infer_type(values[idx]) if not opts.infer_none else values[idx]
        records.append(rec)
    return records

def read_markdown_records(fileobj, opts):
    lines=[]
    for raw in fileobj:
        if opts.skip_comments and raw.lstrip().startswith(opts.comment_prefix):
            continue
        if opts.pass_comments and raw.lstrip().startswith(opts.comment_prefix):
            sys.stdout.write(raw)
            continue
        line = raw.rstrip("\r\n")
        lines.append(line)
    table_lines = [l for l in lines if l.strip().startswith("|")]
    if len(table_lines) < 1:
        return []
    header_line = table_lines[0]
    def split_markdown_row(row):
        row=row.strip()
        if row.startswith("|"):
            row=row[1:]
        if row.endswith("|"):
            row=row[:-1]
        parts = [p.strip() for p in row.split("|")]
        return parts
    header = split_markdown_row(header_line)
    records=[]
    start = 1
    if len(table_lines) > 1 and re.match(r'^\s*\|\s*---', table_lines[1]):
        start = 2
    for line in table_lines[start:]:
        values = split_markdown_row(line)
        rec = OrderedDict()
        for idx, h in enumerate(header):
            if idx < len(values):
                rec[h] = infer_type(values[idx]) if not opts.infer_none else values[idx]
            else:
                rec[h] = ""
        records.append(rec)
    return records

def read_records(opts, ifmt, input_files):
    all_records=[]
    if getattr(opts, 'no_input', False):
        return []
    files = input_files
    if not files:
        files = ["-"]
    for fname in files:
        try:
            if fname == "-":
                f = sys.stdin
                recs = read_records_from_fileobj(f, opts, ifmt, fname)
                all_records.extend(recs)
            else:
                if not os.path.exists(fname):
                    fail(f"mlr: open {fname}: no such file or directory")
                with open(fname, 'r', newline='', encoding='utf-8', errors='replace') as f:
                    recs = read_records_from_fileobj(f, opts, ifmt, fname)
                    all_records.extend(recs)
        except SystemExit:
            raise
        except Exception as e:
            if "Expecting value" in str(e) or "invalid character" in str(e) or "JSON" in str(e):
                msg = str(e)
                eprint(f"mlr: {msg}")
                sys.exit(1)
            else:
                eprint(f"mlr: {e}")
                sys.exit(1)
    return all_records

def read_records_from_fileobj(f, opts, ifmt, fname="<stdin>"):
    if ifmt in ("csv","csvlite","tsv","tsvlite"):
        return read_csv_records(f, opts, ifmt)
    elif ifmt == "dkvp":
        return read_dkvp_records(f, opts)
    elif ifmt == "nidx":
        return read_nidx_records(f, opts)
    elif ifmt == "pprint":
        return read_pprint_records(f, opts)
    elif ifmt == "markdown":
        return read_markdown_records(f, opts)
    elif ifmt == "json":
        content = f.read()
        if not content.strip():
            return []
        try:
            data = json.loads(content)
        except json.JSONDecodeError as e:
            pos = e.pos
            ch = content[pos] if pos < len(content) else '?'
            if "Expecting value" in e.msg:
                fail(f"mlr: invalid character '{ch}' looking for beginning of value")
            elif "Expecting property name" in e.msg:
                fail(f"mlr: invalid character '{ch}' looking for beginning of object key string")
            elif "Unterminated string" in e.msg:
                fail(f"mlr: unexpected end of JSON input")
            else:
                fail(f"mlr: {e.msg}")
        if isinstance(data, list):
            recs=[]
            for item in data:
                if isinstance(item, dict):
                    rec = OrderedDict()
                    for k,v in item.items():
                        rec[k]=v
                    recs.append(rec)
                else:
                    recs.append(OrderedDict({"value": item}))
            return recs
        elif isinstance(data, dict):
            rec = OrderedDict()
            for k,v in data.items():
                rec[k]=v
            return [rec]
        else:
            return []
    elif ifmt == "jsonl":
        recs=[]
        for line in f:
            line=line.strip()
            if not line:
                continue
            if opts.skip_comments and line.lstrip().startswith(opts.comment_prefix):
                continue
            if opts.pass_comments and line.lstrip().startswith(opts.comment_prefix):
                sys.stdout.write(line+"\n")
                continue
            try:
                data = json.loads(line)
                if isinstance(data, dict):
                    rec = OrderedDict()
                    for k,v in data.items():
                        rec[k]=v
                    recs.append(rec)
                else:
                    recs.append(OrderedDict({"value": data}))
            except json.JSONDecodeError as e:
                pos = e.pos
                ch = line[pos] if pos < len(line) else '?'
                if "Expecting value" in e.msg:
                    fail(f"mlr: invalid character '{ch}' looking for beginning of value")
                else:
                    fail(f"mlr: {e.msg}")
        return recs
    elif ifmt == "xtab":
        recs=[]
        cur = OrderedDict()
        for raw in f:
            if opts.skip_comments and raw.lstrip().startswith(opts.comment_prefix):
                continue
            if opts.pass_comments and raw.lstrip().startswith(opts.comment_prefix):
                sys.stdout.write(raw)
                continue
            line = raw.rstrip("\r\n")
            if line.strip() == "":
                if cur:
                    recs.append(cur)
                    cur = OrderedDict()
                continue
            parts = line.strip().split(None,1)
            if len(parts)==2:
                k,v = parts
            elif len(parts)==1:
                k=parts[0]; v=""
            else:
                continue
            cur[k]= infer_type(v) if not opts.infer_none else v
        if cur:
            recs.append(cur)
        return recs
    elif ifmt == "yaml":
        try:
            import yaml
            content = f.read()
            if not content.strip():
                return []
            data = yaml.safe_load(content)
            if isinstance(data, list):
                recs=[]
                for item in data:
                    if isinstance(item, dict):
                        rec = OrderedDict()
                        for k,v in item.items():
                            rec[k]=v
                        recs.append(rec)
                return recs
            elif isinstance(data, dict):
                return [OrderedDict(data)]
            else:
                return []
        except ImportError:
            content = f.read()
            if not content.strip():
                return []
            try:
                data = json.loads(content)
                if isinstance(data, list):
                    return [OrderedDict(d) for d in data if isinstance(d,dict)]
                elif isinstance(data, dict):
                    return [OrderedDict(data)]
                else:
                    return []
            except:
                return []
        except Exception as e:
            fail(f"mlr: {e}")
    elif ifmt == "dcf":
        recs=[]
        cur=OrderedDict()
        for raw in f:
            if opts.skip_comments and raw.lstrip().startswith(opts.comment_prefix):
                continue
            if opts.pass_comments and raw.lstrip().startswith(opts.comment_prefix):
                sys.stdout.write(raw)
                continue
            line = raw.rstrip("\r\n")
            if line.strip() == "":
                if cur:
                    recs.append(cur)
                    cur=OrderedDict()
                continue
            if ":" in line:
                k,v = line.split(":",1)
                cur[k.strip()] = infer_type(v.strip()) if not opts.infer_none else v.strip()
            else:
                cur[line.strip()] = ""
        if cur:
            recs.append(cur)
        return recs
    else:
        return read_dkvp_records(f, opts)

def write_records(records, opts, ofmt):
    if not records:
        return
    if ofmt in ("csv","csvlite","tsv","tsvlite"):
        write_csv_records(records, opts, ofmt)
    elif ofmt == "dkvp":
        for rec in records:
            line = serialize_dkvp(rec, opts.ofs, opts.ops)
            sys.stdout.write(line + (opts.ors if opts.ors else "\n"))
    elif ofmt == "nidx":
        for rec in records:
            keys = list(rec.keys())
            try:
                sorted_keys = sorted(keys, key=lambda x: int(x) if x.isdigit() else x)
            except:
                sorted_keys = keys
            values=[]
            for k in sorted_keys:
                v = rec[k]
                if isinstance(v, (dict, list)):
                    v = json.dumps(v)
                else:
                    v = format_value(v)
                values.append(v)
            line = opts.ofs.join(values) if opts.ofs else " ".join(values)
            sys.stdout.write(line + (opts.ors if opts.ors else "\n"))
    elif ofmt == "pprint":
        fieldnames=[]
        seen=set()
        for rec in records:
            for k in rec.keys():
                if k not in seen:
                    seen.add(k)
                    fieldnames.append(k)
        col_widths = {}
        for fn in fieldnames:
            max_len = len(str(fn))
            for rec in records:
                v = rec.get(fn, "")
                v_str = format_value(v)
                if len(v_str) > max_len:
                    max_len = len(v_str)
            col_widths[fn]=max_len
        header_parts=[]
        for fn in fieldnames:
            w = col_widths[fn]
            header_parts.append(str(fn).ljust(w))
        sys.stdout.write("  ".join(header_parts).rstrip() + "\n")
        for rec in records:
            row_parts=[]
            for fn in fieldnames:
                v = rec.get(fn, "")
                v_str = format_value(v)
                w = col_widths[fn]
                row_parts.append(v_str.ljust(w))
            sys.stdout.write("  ".join(row_parts).rstrip() + "\n")
    elif ofmt == "xtab":
        for rec in records:
            for k,v in rec.items():
                v_str = format_value(v)
                sys.stdout.write(f"{k}{opts.ops}{v_str}\n")
            sys.stdout.write("\n")
    elif ofmt == "markdown":
        fieldnames=[]
        seen=set()
        for rec in records:
            for k in rec.keys():
                if k not in seen:
                    seen.add(k)
                    fieldnames.append(k)
        sys.stdout.write("| " + " | ".join(fieldnames) + " |\n")
        sys.stdout.write("| " + " | ".join(["---"]*len(fieldnames)) + " |\n")
        for rec in records:
            row = [format_value(rec.get(fn,"")) for fn in fieldnames]
            sys.stdout.write("| " + " | ".join(row) + " |\n")
    elif ofmt == "json":
        write_json_records(records, opts, "json")
    elif ofmt == "jsonl":
        write_json_records(records, opts, "jsonl")
    elif ofmt == "yaml":
        try:
            import yaml
            data = [dict(r) for r in records]
            sys.stdout.write(yaml.dump(data, default_flow_style=False))
        except ImportError:
            write_json_records(records, opts, "json")
    elif ofmt == "dcf":
        for rec in records:
            for k,v in rec.items():
                v_str = format_value(v)
                sys.stdout.write(f"{k}: {v_str}\n")
            sys.stdout.write("\n")
    else:
        for rec in records:
            line = serialize_dkvp(rec, opts.ofs, opts.ops)
            sys.stdout.write(line + (opts.ors if opts.ors else "\n"))

# --- DSL handling ---
def dsl_transform(expr, record_var="record", oosvar_var="oosvar"):
    def repl_field(m):
        s = m.group(0)
        if s.startswith("${"):
            name = s[2:-1]
            return f'{record_var}["{name}"]'
        elif s.startswith('$[['):
            inner = s[3:-2]
            return f'{record_var}[{inner}]'
        elif s.startswith('$['):
            inner = s[2:-1]
            inner = inner.strip().strip('"').strip("'")
            return f'{record_var}["{inner}"]'
        else:
            name = s[1:]
            return f'{record_var}["{name}"]'
    pattern_field = r'\$\{[^}]+\}|\$\[\[[^\]]+\]\]|\$\[[^\]]+\]|\$[A-Za-z_][A-Za-z0-9_]*'
    expr = re.sub(pattern_field, repl_field, expr)
    def repl_oos(m):
        s = m.group(0)
        if s.startswith("@{"):
            name = s[2:-1]
            return f'{oosvar_var}["{name}"]'
        elif s.startswith("@["):
            inner = s[2:-1]
            inner = inner.strip().strip('"').strip("'")
            return f'{oosvar_var}["{inner}"]'
        elif s.startswith("@"):
            name = s[1:]
            return f'{oosvar_var}["{name}"]'
        else:
            return s
    pattern_oos = r'@\{[^}]+\}|@\[[^\]]+\]|@[A-Za-z_][A-Za-z0-9_]*'
    expr = re.sub(pattern_oos, repl_oos, expr)
    expr = expr.replace("&&", " and ")
    expr = expr.replace("||", " or ")
    def repl_regex_match(m):
        left = m.group(1).strip()
        op = m.group(2)
        pat = m.group(3)
        flags = m.group(4) or ""
        if pat[0] == '"' and pat[-1] == '"' or pat[0] == "'" and pat[-1] == "'":
            inner = pat[1:-1]
        else:
            inner = pat
        flag_expr = "re.IGNORECASE" if "i" in flags else "0"
        if op == "=~":
            return f'bool(re.search({repr(inner)}, str({left}), flags={flag_expr}))'
        else:
            return f'not bool(re.search({repr(inner)}, str({left}), flags={flag_expr}))'
    regex_match_pat = re.compile(r'(\S+)\s*(=~|!~)\s*(".*?"|\'.*?\')([iI]?)')
    while True:
        m = regex_match_pat.search(expr)
        if not m:
            break
        left, op, pat, fl = m.group(1), m.group(2), m.group(3), m.group(4)
        replacement = repl_regex_match(m)
        expr = expr[:m.start()] + replacement + expr[m.end():]
    expr = re.sub(r'!\s*(?!=)', ' not ', expr)
    expr = re.sub(r'\btrue\b', 'True', expr)
    expr = re.sub(r'\bfalse\b', 'False', expr)
    expr = re.sub(r'\bnull\b', 'None', expr)
    return expr

def eval_dsl_expression(expr, record, oosvar, context):
    globs = {
        "re": re, "math": math, "json": json, "random": random, "statistics": statistics,
        "int": int, "float": float, "str": str, "bool": bool, "len": len,
        "abs": abs, "min": min, "max": max, "sum": sum,
        "log": math.log, "log10": math.log10, "sqrt": math.sqrt, "exp": math.exp,
        "ceil": math.ceil, "floor": math.floor, "round": round,
        "sin": math.sin, "cos": math.cos, "tan": math.tan,
        "asin": math.asin, "acos": math.acos, "atan": math.atan,
        "sinh": math.sinh, "cosh": math.cosh, "tanh": math.tanh,
        "asinh": math.asinh, "acosh": math.acosh, "atanh": math.atanh,
        "mean": statistics.mean, "median": statistics.median,
        "toupper": lambda s: str(s).upper(),
        "tolower": lambda s: str(s).lower(),
        "length": lambda s: len(str(s)),
        "strlen": lambda s: len(str(s)),
        "strip": lambda s: str(s).strip(),
        "lstrip": lambda s: str(s).lstrip(),
        "rstrip": lambda s: str(s).rstrip(),
        "sub": lambda s, pat, repl: re.sub(pat, repl, str(s)),
        "gsub": lambda s, pat, repl: re.sub(pat, repl, str(s)),
        "substr": lambda s, start, length=None: str(s)[start-1:start-1+length] if length else str(s)[start-1:],
        "urand": random.random,
        "urandint": lambda a,b: random.randint(a,b),
        "print": lambda *args, **kwargs: sys.stdout.write(" ".join(str(a) for a in args)+"\n"),
        "printn": lambda *args, **kwargs: sys.stdout.write(" ".join(str(a) for a in args)),
        "eprint": lambda *args, **kwargs: sys.stderr.write(" ".join(str(a) for a in args)+"\n"),
        "eprintn": lambda *args, **kwargs: sys.stderr.write(" ".join(str(a) for a in args)),
    }
    globs.update(context)
    env = {}
    env.update(globs)
    env.update({"record": record, "oosvar": oosvar})
    env.update(context)
    py_expr = dsl_transform(expr, "record", "oosvar")
    stmts = [s.strip() for s in py_expr.split(";") if s.strip()!=""]
    last_val = None
    for stmt in stmts:
        stmt = stmt.strip()
        if stmt.startswith("{") and stmt.endswith("}"):
            stmt = stmt[1:-1].strip()
        if not stmt:
            continue
        assignment_ops = ["+=", "-=", "*=", "/=", "%=", "**=", ".=", "||=", "&&=", "//=", ".+", ".-", "??=", "???="]
        is_assignment = False
        for op in assignment_ops:
            if op in stmt:
                is_assignment = True
                break
        if not is_assignment:
            if re.search(r'(?<![=!<>~])=(?!=)(?!~)', stmt):
                is_assignment = True
        if is_assignment:
            stmt = stmt.replace(".=", "+=")
            try:
                exec(stmt, env, env)
            except Exception as e:
                try:
                    last_val = eval(stmt, env, env)
                except Exception as e2:
                    eprint(f"mlr: cannot parse DSL expression.\nmlr: {e2}")
                    return False
            continue
        else:
            try:
                if stmt.strip().startswith(("if","for","while","func","subr","begin","end")):
                    exec(stmt, env, env)
                    last_val = None
                else:
                    last_val = eval(stmt, env, env)
            except SyntaxError:
                try:
                    exec(stmt, env, env)
                except Exception as e:
                    eprint(f"mlr: cannot parse DSL expression.\nmlr: {e}")
                    return False
            except Exception as e:
                eprint(f"mlr: {e}")
                return False
    return last_val
'''

