def dsl_transform(expr, record_var="record", oosvar_var="oosvar"):
    def repl_field(m):
        s = m.group(0)
        if s.startswith("${"):
            name = s[2:-1]
            return f'{record_var}["{name}"]'
        elif s.startswith('$[['):
            inner = s[3:-2]
            return f'{record_var}[{inner}]'
        elif s.startswith('$['):
            inner = s[2:-1]
            inner = inner.strip().strip('"').strip("'")
            return f'{record_var}["{inner}"]'
        else:
            name = s[1:]
            return f'{record_var}["{name}"]'
    pattern_field = r'\$\{[^}]+\}|\$\[\[[^\]]+\]\]|\$\[[^\]]+\]|\$[A-Za-z_][A-Za-z0-9_]*'
    expr = re.sub(pattern_field, repl_field, expr)
    def repl_oos(m):
        s = m.group(0)
        if s.startswith("@{"):
            name = s[2:-1]
            return f'{oosvar_var}["{name}"]'
        elif s.startswith("@["):
            inner = s[2:-1]
            inner = inner.strip().strip('"').strip("'")
            return f'{oosvar_var}["{inner}"]'
        elif s.startswith("@"):
