    while i < len(args):
        a=args[i]
        if a=="--fill-with":
            if i+1>=len(args):
                fail('mlr: mlr unsparsify: --fill-with requires an argument')
            fill_with=args[i+1]
            i+=2
        elif a=="-f":
            if i+1>=len(args):
                fail('mlr: mlr unsparsify: -f requires an argument')
            fields=args[i+1].split(",")
            i+=2
        elif a in ("-h","--help"):
            sys.stdout.write(VERB_HELP.get("unsparsify",""))
            sys.exit(0)
        else:
            fail(f'mlr: mlr unsparsify: option "{a}" not recognized')
    if not records:
        return records
    if fields is not None:
        union=set(fields)
        result=[]
        for rec in records:
            new_rec=OrderedDict(rec)
            for k in union:
                if k not in new_rec:
                    new_rec[k]=fill_with
            result.append(new_rec)
        return result
    else:
        all_keys=set()
        for rec in records:
            all_keys.update(rec.keys())
        ordered_keys=[]
        seen=set()
        for rec in records:
            for k in rec.keys():
                if k not in seen:
                    seen.add(k)
                    ordered_keys.append(k)
        for k in all_keys:
            if k not in seen:
                ordered_keys.append(k)
        result=[]
        for rec in records:
            new_rec=OrderedDict()
            for k in ordered_keys:
                if k in rec:
                    new_rec[k]=rec[k]
                else:
                    new_rec[k]=fill_with
            result.append(new_rec)
        return result

