                    emitted.append(rec)
            result.extend(emitted)
        else:
            dummy_rec=OrderedDict()
            ctx={"NR":NR,"FNR":FNR,"NF":0,"FILENAME":"", "FILENUM":0}
            eval_dsl_expression(end_code, dummy_rec, oosvar, ctx)
    return result

def verb_stats1(records, args, opts, gbl):
    accs=[]
    value_fields=[]
    group_by=[]
    i=0
    while i < len(args):
        a=args[i]
        if a=="-a":
            if i+1>=len(args):
                fail('mlr: mlr stats1: -a requires an argument')
            accs=args[i+1].split(",")
            i+=2
        elif a=="-f":
            if i+1>=len(args):
                fail('mlr: mlr stats1: -f requires an argument')
            value_fields=args[i+1].split(",")
            i+=2
        elif a=="-g":
            if i+1>=len(args):
                fail('mlr: mlr stats1: -g requires an argument')
            group_by=args[i+1].split(",")
            i+=2
        elif a.startswith("--fr") or a.startswith("--fx") or a.startswith("--gr") or a.startswith("--gx"):
            if i+1 < len(args) and not args[i+1].startswith("-"):
                i+=2
            else:
                i+=1
        elif a in ("-i","-s"):
            i+=1
        elif a in ("-h","--help"):
            sys.stdout.write(VERB_HELP.get("stats1",""))
            sys.exit(0)
        else:
            if a.startswith("-"):
                fail(f'mlr: mlr stats1: option "{a}" not recognized')
            else:
                fail(f'mlr: mlr stats1: option "{a}" not recognized')
    if not accs:
        fail('mlr: mlr stats1: -a requires an argument')
    if not value_fields:
        fail('mlr: mlr stats1: -f requires an argument')
    groups=collections.OrderedDict()
    if group_by:
        for rec in records:
            key=tuple(rec.get(g,"") for g in group_by)
            if key not in groups:
                groups[key]=[]
            groups[key].append(rec)
    else:
        groups[None]=records
    result=[]
    for key, group_recs in groups.items():
        out_rec=OrderedDict()
        if group_by and key is not None:
            for idx,g in enumerate(group_by):
                out_rec[g]=key[idx]
        for vf in value_fields:
            vals=[]
            for r in group_recs:
                if vf in r and r[vf]!="" and r[vf] is not None:
                    vals.append(r[vf])
            for acc in accs:
                acc=acc.strip()
                out_key=f"{vf}_{acc}"
                if acc=="count":
                    cnt=len([r for r in group_recs if vf in r])
                    out_rec[out_key]=cnt
                elif acc=="null_count":
                    cnt=len([r for r in group_recs if vf not in r or r[vf]=="" or r[vf] is None])
                    out_rec[out_key]=cnt
                elif acc=="distinct_count":
                    seen=set(str(r.get(vf,"")) for r in group_recs)
                    out_rec[out_key]=len(seen)
                elif acc=="sum":
                    try:
                        s=sum(float(v) for v in vals)
                        if s.is_integer():
                            s=int(s)
                        out_rec[out_key]=s
                    except:
                        out_rec[out_key]=0
                elif acc=="mean":
                    try:
                        nums=[float(v) for v in vals]
                        m=statistics.mean(nums) if nums else 0
                        out_rec[out_key]=m
                    except:
                        out_rec[out_key]=0
                elif acc=="median":
                    try:
                        nums=sorted(float(v) for v in vals)
                        m=statistics.median(nums) if nums else 0
                        out_rec[out_key]=m
                    except:
                        out_rec[out_key]=0
                elif acc in ("p10","p25","p50","p90","p100","min","max"):
                    try:
                        nums=sorted(float(v) for v in vals)
                        if not nums:
                            out_rec[out_key]=None
                        else:
                            if acc=="min":
                                out_rec[out_key]=nums[0]
                            elif acc=="max":
                                out_rec[out_key]=nums[-1]
                            else:
                                p_str=acc[1:] if acc.startswith("p") else acc
                                p=float(p_str)
                                n=len(nums)
                                idx=p/100*(n-1)
                                lo=int(math.floor(idx))
                                hi=int(math.ceil(idx))
                                if lo==hi:
                                    out_rec[out_key]=nums[lo]
                                else:
                                    d=idx-lo
                                    out_rec[out_key]=nums[lo]*(1-d)+nums[hi]*d
                            if isinstance(out_rec[out_key], float) and out_rec[out_key].is_integer():
                                out_rec[out_key]=int(out_rec[out_key])
                    except:
                        out_rec[out_key]=0
                elif acc=="mode":
                    try:
                        cnt=collections.Counter(str(v) for v in vals)
                        if cnt:
                            most=cnt.most_common(1)[0][0]
                            for v in vals:
                                if str(v)==most:
                                    out_rec[out_key]=v
                                    break
                            else:
                                out_rec[out_key]=most
                        else:
                            out_rec[out_key]=""
                    except:
                        out_rec[out_key]=""
                elif acc=="antimode":
                    try:
                        cnt=collections.Counter(str(v) for v in vals)
                        if cnt:
                            least=cnt.most_common()[-1][0]
                            for v in vals:
                                if str(v)==least:
                                    out_rec[out_key]=v
                                    break
                            else:
                                out_rec[out_key]=least
                        else:
                            out_rec[out_key]=""
                    except:
                        out_rec[out_key]=""
                elif acc=="var":
                    try:
                        nums=[float(v) for v in vals]
                        out_rec[out_key]=statistics.variance(nums) if len(nums)>1 else 0
                    except:
                        out_rec[out_key]=0
                elif acc=="stddev":
                    try:
                        nums=[float(v) for v in vals]
                        out_rec[out_key]=statistics.stdev(nums) if len(nums)>1 else 0
                    except:
                        out_rec[out_key]=0
                elif acc=="skewness" or acc=="kurtosis" or acc=="meaneb" or acc=="mad":
                    out_rec[out_key]=0
                elif acc=="minlen":
                    try:
                        lens=[len(str(v)) for v in vals]
                        out_rec[out_key]=min(lens) if lens else 0
                    except:
                        out_rec[out_key]=0
                elif acc=="maxlen":
                    try:
                        lens=[len(str(v)) for v in vals]
                        out_rec[out_key]=max(lens) if lens else 0
                    except:
                        out_rec[out_key]=0
                else:
                    if acc.startswith("p"):
                        try:
                            p=float(acc[1:])
                            nums=sorted(float(v) for v in vals)
                            if not nums:
                                out_rec[out_key]=0
                            else:
                                n=len(nums)
                                idx=p/100*(n-1)
                                lo=int(math.floor(idx)); hi=int(math.ceil(idx))
                                if lo==hi:
                                    out_rec[out_key]=nums[lo]
                                else:
                                    d=idx-lo
                                    out_rec[out_key]=nums[lo]*(1-d)+nums[hi]*d
                                if isinstance(out_rec[out_key], float) and out_rec[out_key].is_integer():
                                    out_rec[out_key]=int(out_rec[out_key])
                        except:
                            out_rec[out_key]=0
                    else:
                        out_rec[out_key]=0
        result.append(out_rec)
    return result

def verb_grep(records, args, opts, gbl):
    pattern=None
    ignore_case=False
    invert=False
    i=0
    while i < len(args):
        a=args[i]
        if a=="-i":
            ignore_case=True
            i+=1
        elif a=="-v":
            invert=True
            i+=1
        elif a=="-a":
            i+=1
        elif a in ("-h","--help"):
            sys.stdout.write(VERB_HELP.get("grep",""))
            sys.exit(0)
        elif a.startswith("-"):
            fail(f'mlr: mlr grep: option "{a}" not recognized')
        else:
            if pattern is None:
                pattern=a
                i+=1
            else:
                fail(f'mlr: mlr grep: option "{a}" not recognized')
    if pattern is None:
        fail('mlr: mlr grep: regex required')
    flags=re.IGNORECASE if ignore_case else 0
    try:
        pat=re.compile(pattern, flags)
    except re.error as e:
        fail(f"mlr: grep regex error: {e}")
    result=[]
    for rec in records:
        matched=False
        for v in rec.values():
            if pat.search(str(v)):
