        cnt=len(seen)
        if show_only:
            return [OrderedDict([(out_name, cnt)])]
        else:
            groups=collections.Counter()
            for rec in records:
                key=tuple(rec.get(g,"") for g in group_fields)
                groups[key]+=1
            result=[]
            for key,cnt2 in groups.items():
                out_rec=OrderedDict()
                for idx,g in enumerate(group_fields):
                    out_rec[g]=key[idx]
                out_rec[out_name]=cnt2
                result.append(out_rec)
            return result

def verb_rename(records, args, opts, gbl):
    is_regex=False
    group_fields=None
    pairs=[]
    i=0
    while i < len(args):
        a=args[i]
        if a=="-r":
            is_regex=True
            i+=1
        elif a=="-g":
            if i+1>=len(args):
                fail('mlr: mlr rename: -g requires an argument')
            group_fields=args[i+1].split(",")
            i+=2
        elif a in ("-h","--help"):
            sys.stdout.write(VERB_HELP.get("rename",""))
            sys.exit(0)
        elif a.startswith("-"):
            fail(f'mlr: mlr rename: option "{a}" not recognized')
        else:
            parts=a.split(",")
            if len(parts)%2!=0:
                fail('mlr: mlr rename: rename pairs must be even')
            for j in range(0,len(parts),2):
                pairs.append((parts[j], parts[j+1]))
            i+=1
    if not pairs:
        fail('mlr: mlr rename: no rename pairs provided')
    result=[]
    for rec in records:
        new_rec=OrderedDict()
        for k,v in rec.items():
            new_k=k
            for old,new in pairs:
                if is_regex:
                    pat=old
                    flags=0
                    if pat.startswith('"') and pat.endswith('"'):
                        pat=pat[1:-1]
                    elif pat.startswith("'") and pat.endswith("'"):
                        pat=pat[1:-1]
                    try:
                        new_k=re.sub(pat, new, new_k, flags=flags)
                    except re.error as e:
                        fail(f"mlr: rename regex error: {e}")
                else:
                    if k==old:
                        new_k=new
            new_rec[new_k]=v
        result.append(new_rec)
    return result

