            if i+1>=len(args):
                fail('mlr: mlr filter: -s requires an argument')
            kv=args[i+1]
            if "=" not in kv:
                fail('mlr: mlr filter: -s requires name=value')
            k,v=kv.split("=",1)
            predefined[k]=infer_type(v)
            i+=2
        elif a=="-x":
