            i+=1
        elif a in ("-h","--help"):
            sys.stdout.write(VERB_HELP.get("filter",""))
            sys.exit(0)
        elif a.startswith("-"):
            fail(f'mlr: mlr filter: option "{a}" not recognized')
        else:
            expr_parts.append(a)
            i+=1
            break
    if not expr_parts:
        fail('mlr: mlr filter: DSL expression required')
    expr=";".join(expr_parts)
    oosvar=OrderedDict()
    for k,v in predefined.items():
        oosvar[k]=v
    begin_m=re.search(r'begin\s*\{([^}]*)\}', expr, re.DOTALL)
    if begin_m:
        begin_code=begin_m.group(1)
        expr=expr[:begin_m.start()]+expr[begin_m.end():]
        dummy_rec=OrderedDict()
        ctx={"NR":0,"FNR":0,"NF":0,"FILENAME":"", "FILENUM":0}
        eval_dsl_expression(begin_code, dummy_rec, oosvar, ctx)
    result=[]
    NR=0
    FNR=0
    for idx, rec in enumerate(records):
        NR+=1
        FNR+=1
        NF=len(rec)
        ctx={"NR":NR,"FNR":FNR,"NF":NF,"FILENAME":"(stdin)","FILENUM":1,"M_PI":math.pi,"M_E":math.e}
        rec_copy=OrderedDict(rec)
        val=eval_dsl_expression(expr, rec_copy, oosvar, ctx)
        keep=bool(val) if val is not None else False
        if invert:
            keep=not keep
        if not quiet and keep:
            result.append(rec_copy)
    return result

