    begin_m=re.search(r'begin\s*\{([^}]*)\}', expr, re.DOTALL)
    if begin_m:
        begin_code=begin_m.group(1)
        expr=expr[:begin_m.start()]+expr[begin_m.end():]
        dummy_rec=OrderedDict()
        ctx={"NR":0,"FNR":0,"NF":0,"FILENAME":"", "FILENUM":0, "M_PI":math.pi, "M_E":math.e}
        eval_dsl_expression(begin_code, dummy_rec, oosvar, ctx)
    end_m=re.search(r'end\s*\{([^}]*)\}', expr, re.DOTALL)
    end_code=None
    if end_m:
        end_code=end_m.group(1)
        expr=expr[:end_m.start()]+expr[end_m.end():]
    result=[]
